// castord's stacks module decides as @pc/stacks and stacks.ts do, case for
// case (fixtures/stacks.json, generated by gen-stacks.mts).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use castord::stacks::{self, image, render, spec};
use serde_json::{Value, json};

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/stacks.json")).unwrap()
}

fn strs(v: &Value) -> Vec<String> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_str().unwrap().to_owned())
        .collect()
}

fn pairs(v: &Value) -> Vec<(String, String)> {
    v.as_object()
        .unwrap()
        .iter()
        .map(|(k, x)| (k.clone(), x.as_str().unwrap().to_owned()))
        .collect()
}

#[test]
fn checks_definitions_like_check_stack() {
    let f = fixture();
    for case in f["docs"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        match spec::check(&case["doc"]) {
            Ok(s) => {
                assert!(
                    case.get("problems").is_none(),
                    "{name}: accepted, but {}",
                    case["problems"]
                );
                assert_eq!(serde_json::to_value(&s).unwrap(), case["spec"], "{name}");
                assert_eq!(serde_json::to_value(s.units()).unwrap(), case["units"], "{name}");
                assert_eq!(s.secret_names(), strs(&case["secrets"]), "{name}");
            }
            Err(e) => assert_eq!(json!(e.0), case["problems"], "{name}"),
        }
    }
}

#[test]
fn a_checked_spec_written_back_checks_the_same() {
    // A stored spec is re-checked before it runs: as a compose document again,
    // it must come out identical.
    let f = fixture();
    for case in f["docs"].as_array().unwrap() {
        let Ok(s) = spec::check(&case["doc"]) else { continue };
        let back = s.to_document();
        assert_eq!(spec::check(&back).as_ref(), Ok(&s), "{}", case["name"]);
    }
}

#[test]
fn reads_what_the_portal_stores() {
    let f = fixture();
    for case in f["stored"].as_array().unwrap() {
        let s = spec::parse_stored(case["definition"].as_str().unwrap()).unwrap();
        assert_eq!(serde_json::to_value(&s).unwrap(), case["spec"]);
    }
    assert!(spec::parse_stored("services:\n  app: {}\n").is_err());
    assert!(
        spec::parse_stored(&format!("[{}1]", "1,".repeat(40_000)))
            .unwrap_err()
            .0[0]
            .contains("larger than 64 KB")
    );
}

#[test]
fn image_references() {
    let f = fixture();
    for case in f["images"].as_array().unwrap() {
        let input = case[0].as_str().unwrap();
        let got = match image::parse(input) {
            Ok(r) => serde_json::to_value(r).unwrap(),
            Err(e) => json!({ "error": e }),
        };
        assert_eq!(got, case[1], "{input}");
    }
    let ghcr = image::parse("ghcr.io/immich-app/immich-server:v2").unwrap();
    assert_eq!(
        image::pinned(&ghcr, f["digest"].as_str().unwrap()).unwrap(),
        f["pinned"]
    );
    assert!(image::pinned(&ghcr, "sha256:12").is_err());
    for case in f["digests"].as_array().unwrap() {
        let r = image::parse(case["ref"]["canonical"].as_str().unwrap()).unwrap();
        assert_eq!(
            json!(image::digest_for(&r, &strs(&case["list"]))),
            case["digest"],
            "{case}"
        );
    }
    for case in f["memory"].as_array().unwrap() {
        assert_eq!(
            json!(spec::parse_memory(&case[0]).map(stacks::js::num)),
            case[1],
            "{case}"
        );
    }
}

#[test]
fn renders_like_render_ts() {
    let f = fixture();
    let docs = f["docs"].as_array().unwrap();
    for case in f["render"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let doc = docs.iter().find(|d| d["name"] == name).unwrap();
        let s = spec::check(&doc["doc"]).unwrap();
        let c = &case["ctx"];
        let images = pairs(&c["images"]);
        let secrets = pairs(&c["secrets"]);
        let ctx = render::Context {
            slug: c["slug"].as_str().unwrap(),
            stack: c["stack"].as_str().unwrap(),
            origin: c["origin"].as_str().unwrap(),
            data_dir: c["dataDir"].as_str().unwrap(),
            images: &images,
            secrets: &secrets,
            runtime: c["runtime"].as_str(),
            egress_image: c["egressImage"].as_str().unwrap(),
        };
        let out = render::compose(&s, &ctx).unwrap();
        assert_eq!(out, case["out"], "{name}");
        // Written as compose.json, byte for byte what JSON.stringify(_, null, 2) writes.
        assert_eq!(
            serde_json::to_string_pretty(&out).unwrap(),
            serde_json::to_string_pretty(&case["out"]).unwrap()
        );
        let unpinned = [("app".to_owned(), "nginx:latest".to_owned())];
        let bad = render::Context {
            images: &unpinned,
            ..ctx
        };
        assert_eq!(
            render::compose(&s, &bad).unwrap_err(),
            "app: image not pinned to a digest"
        );
    }
    let rendered = spec::check(&docs.iter().find(|d| d["name"] == "rendered").unwrap()["doc"]).unwrap();
    let images = pairs(&f["render"][0]["ctx"]["images"]);
    let ctx = render::Context {
        slug: "muster",
        stack: "links",
        origin: "https://links-muster.castorapps.ch",
        data_dir: "/d",
        images: &images,
        secrets: &[("db".into(), "x".into())],
        runtime: None,
        egress_image: "e",
    };
    assert_eq!(render::compose(&rendered, &ctx).unwrap_err(), "secret api_key missing");

    assert_eq!(
        serde_json::to_value(render::names("muster", "links")).unwrap(),
        f["names"][0]
    );
    assert_eq!(serde_json::to_value(render::names("a-b", "c")).unwrap(), f["names"][1]);
    assert!(render::is_edge_network(&render::names("a-b", "c").edge_network));
    for bad in [
        "pc-s-a-b-c-edge",
        "pc-s---c-edge",
        "pc-s-a--b-c-edge",
        "pc-s-a--B-edge",
        "pc-s-a--b-edgex",
    ] {
        assert!(!render::is_edge_network(bad), "{bad}");
    }
    assert_eq!(
        render::node_route("muster", "links", "links-muster.castorapps.ch", 9090.0),
        f["node_route"]
    );
    assert_eq!(
        render::node_middlewares(&["10.0.0.1".into(), "10.0.0.2".into()]).unwrap(),
        f["middlewares"]
    );
    assert!(render::node_middlewares(&[]).is_err());
    let two = [
        ("links".to_owned(), "links-muster.castorapps.ch".to_owned()),
        ("tools".to_owned(), "tools-muster.castorapps.ch".to_owned()),
    ];
    assert_eq!(
        render::control_plane_routes("muster", &two, "http://10.0.0.40:8480", Some("le"), "castorapps.ch"),
        f["control_plane"][0]
    );
    let one = [("links".to_owned(), "links-muster.castor.test".to_owned())];
    assert_eq!(
        render::control_plane_routes("muster", &one, "http://10.0.0.40:8480", None, "castor.test"),
        f["control_plane"][1]
    );
}

#[test]
fn users_volumes_and_bookings_like_stacks_ts() {
    let f = fixture();
    let (passwd, group) = (f["passwd"].as_str().unwrap(), f["group"].as_str().unwrap());
    let ids: serde_json::Map<String, Value> = stacks::parse_ids(passwd)
        .into_iter()
        .map(|(k, v)| (k, json!(v)))
        .collect();
    assert_eq!(Value::Object(ids), f["ids"]);
    let files = stacks::IdFiles { passwd, group };
    // The cases without files are the ones resolveUser got none for.
    let without = ["", "1000", "1000:50", "70000", "1:70000", ":5"];
    for (i, case) in f["users"].as_array().unwrap().iter().enumerate() {
        let u = case[0].as_str().unwrap();
        let with_files = !(without.contains(&u) || i == 12);
        let got = match stacks::resolve_user(u, with_files.then_some(&files)) {
            Ok((uid, gid)) => json!({ "uid": uid, "gid": gid }),
            Err(e) => json!({ "error": e }),
        };
        assert_eq!(got, case[1], "{u}");
    }
    for case in f["uncovered"].as_array().unwrap() {
        let mounts = strs(&case["mounts"]);
        let mounts: Vec<&str> = mounts.iter().map(String::as_str).collect();
        assert_eq!(
            stacks::uncovered_volumes(&strs(&case["declared"]), &mounts),
            strs(&case["open"]),
            "{case}"
        );
    }
    for case in f["cover"].as_array().unwrap() {
        let list = case["stacks"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| {
                (
                    s["id"].as_str().unwrap().to_owned(),
                    serde_json::from_value(s["units"].clone()).unwrap(),
                )
            })
            .collect();
        let (ok, over) = stacks::covered(list, serde_json::from_value(case["booked"].clone()).unwrap());
        assert_eq!(ok, strs(&case["covered"]));
        assert_eq!(over, strs(&case["over"]));
    }
}
